SELECT COUNT(DISTINCT "MulheresMil_1"."Calculation_838513981462429699") AS "ctd_Calculation_838513981462429699_ok",   CAST(EXTRACT(YEAR FROM "MulheresMil_1"."data_de_inicio") AS BIGINT) AS "yr_data_de_inicio_ok" FROM "MulheresMil_1" WHERE ((NOT (("MulheresMil_1"."nome_da_sit_matricula__situacao_detalhada_" NOT IN ('', 'INTEGRALIZADA', 'TRANCADA', 'EM_CURSO', 'EM_DEPENDÊNCIA')) OR ("MulheresMil_1"."nome_da_sit_matricula__situacao_detalhada_" IS NULL))) AND (NOT ("MulheresMil_1"."situacao_da_turma" IN ('CANCELADA', 'CRIADA', 'PUBLICADA')))) GROUP BY "yr_data_de_inicio_ok";
